            var keyCache = new Dictionary<(AchievementType, string), AchievementDataKey>();
            foreach (var row in rows("achievement"))
            {
                var type = (AchievementType)Convert.ToInt32(row["AchievementType"]);
                if (type != AchievementType.NpcFriendshipLevel && type != AchievementType.StarGodNpcFriendshipLevel) continue;
