            if (type == AchievementType.StarGodNpcFriendshipLevel) return (AchievementDataKey)JsonConvert.DeserializeObject<AchievementDataKeyStarGodNpcFriendshipLevel>(json) ?? new AchievementDataKeyNormal(type);
